package dev.cosmerearcanists.hemalurgy;

import dev.cosmerearcanists.compounding.*;
import dev.cosmerearcanists.power.*;
import java.util.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.ai.attributes.*;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.component.CustomData;
import net.neoforged.bus.api.*;
import net.neoforged.neoforge.event.entity.player.PlayerEvent;
import net.neoforged.neoforge.event.tick.PlayerTickEvent;

/** Persistent body implants own real item singletons. Menus only display copies of this state. */
public final class ImplantService {
    private static final String KEY="hemalurgic_implants",WOUNDS="hemalurgic_wounds";
    public static final String DISPLAY="cosmerearcanists_implant_display";
    public record Implant(int point,double u,double v,ItemStack item){public HemalurgicSpikes.Charge charge(){return HemalurgicSpikes.contents(item);}}
    public static boolean configured(){return PowerConfig.ENABLED.get()&&dev.cosmerearcanists.ServerConfig.HEMALURGY_ENABLED.get()&&HemalurgyConfig.ENABLED.get()&&HemalurgyConfig.IMPLANTS.get();}
    private static long now(ServerPlayer p){return p.server.overworld().getGameTime();}
    public static List<Implant> implants(ServerPlayer p){var list=PowerData.data(p).getList(KEY,Tag.TAG_COMPOUND);var out=new ArrayList<Implant>();var points=new HashSet<Integer>();var charges=new HashSet<UUID>();if(list.size()>13)return List.of();for(int i=0;i<list.size();i++){var t=list.getCompound(i);int point=t.getInt("point");double u=t.getDouble("u"),v=t.getDouble("v");var item=ItemStack.parseOptional(p.registryAccess(),t.getCompound("item"));var charge=HemalurgicSpikes.contents(item);if(point<0||point>=13||!ImplantRules.body(u,v)||charge==null||!points.add(point)||!charges.add(charge.id()))return List.of();out.add(new Implant(point,u,v,item));}return List.copyOf(out);}
    private static boolean intact(ServerPlayer p){return PowerData.data(p).getList(KEY,Tag.TAG_COMPOUND).size()==implants(p).size();}
    private static void write(ServerPlayer p,List<Implant> implants){var list=new ListTag();for(var implant:implants){var t=new CompoundTag();t.putInt("point",implant.point());t.putDouble("u",implant.u());t.putDouble("v",implant.v());t.put("item",implant.item().save(p.registryAccess()));list.add(t);}PowerData.data(p).put(KEY,list);}
    public static double accuracy(Implant i){var c=i.charge();return c!=null&&ImplantRules.compatible(c.metal(),c.power(),i.point())?ImplantRules.accuracy(i.point(),i.u(),i.v(),HemalurgyConfig.ACCURACY_RADIUS.get()):0;}
    private static boolean effects(ServerPlayer p){return configured()&&p.isAlive()&&!p.isRemoved()&&!p.isSpectator()&&!AluminumSuppression.active(p);}
    public static List<Implant> active(ServerPlayer p){return !effects(p)?List.of():implants(p).stream().filter(i->HemalurgyService.enabled(i.charge().metal())&&accuracy(i)>0&&(i.charge().trait()||HemalurgySources.enabled(i.charge().power()))).toList();}
    public static boolean linchpin(ServerPlayer p){return implants(p).stream().anyMatch(i->i.point()==12&&accuracy(i)>0&&HemalurgyService.enabled(i.charge().metal()));}
    public static List<StolenConnection> connections(ServerPlayer p){return active(p).stream().filter(i->i.charge().connection()!=null).map(i->{var c=i.charge().connection();var bonds=new HashMap<UUID,Double>();c.players().forEach((id,strength)->bonds.put(id,strength*accuracy(i)));return new StolenConnection(c.identity(),c.homeWorld(),bonds);}).toList();}
    private static boolean scadrial(StolenConnection c){return c!=null&&(c.homeWorld().equals("scadrial")||c.homeWorld().equals("cosmerearcanists:scadrial"));}
    public static boolean connected(ServerPlayer p){return ScadrialVisits.observe(p)||IdentityAccess.implanted(p).stream().anyMatch(ImplantService::scadrial);}
    private static boolean scadrial(ItemStack item){var c=HemalurgicSpikes.contents(item);return c!=null&&c.metal().equals("duralumin")&&scadrial(c.connection())&&HemalurgyService.enabled("duralumin");}
    public static boolean screenAllowed(ServerPlayer p){if(!configured())return false;if(connected(p)||scadrial(p.containerMenu.getCarried()))return true;for(var item:p.getInventory().items)if(scadrial(item))return true;for(var i:implants(p))if(scadrial(i.item()))return true;return false;}
    public static double integrityCost(ServerPlayer p){if(!configured())return 0;var live=implants(p);double cost=ImplantRules.activeCost(live.size(),linchpin(p),HemalurgyConfig.SPIKE_COST.get(),HemalurgyConfig.EXTRA_PENALTY.get());var occupied=new HashSet<Integer>();live.forEach(i->occupied.add(i.point()));var wounds=PowerData.data(p).getCompound(WOUNDS);for(int point=0;point<13;point++)if(!occupied.contains(point)){var t=wounds.getCompound(Integer.toString(point));if(t.getLong("until")>now(p)){double amount=t.getDouble("cost");if(Double.isFinite(amount)&&amount>0)cost+=amount;}}return cost;}
    public static boolean misplaced(ServerPlayer p){if(!configured())return false;var wounds=PowerData.data(p).getCompound(WOUNDS);for(int point=0;point<13;point++)if(wounds.getCompound(Integer.toString(point)).getLong("misplaced_until")>now(p))return true;return false;}
    private static void wound(ServerPlayer p,int point,double cost,boolean removal,boolean mistake){var all=PowerData.data(p).getCompound(WOUNDS);var t=all.getCompound(Integer.toString(point));if(removal){t.putLong("until",now(p)+ImplantRules.WEEK);t.putDouble("cost",cost);}if(mistake)t.putLong("misplaced_until",now(p)+ImplantRules.DAY);all.put(Integer.toString(point),t);PowerData.data(p).put(WOUNDS,all);}
    public static boolean place(ServerPlayer p,boolean back,double u,double v){if(!p.isAlive()||p.isSpectator()||!screenAllowed(p)||!intact(p))return false;var menu=p.containerMenu;var carried=menu.getCarried();var charge=HemalurgicSpikes.contents(carried);int point=ImplantRules.nearest(back,u,v);var live=new ArrayList<>(implants(p));if(charge==null||!connected(p)&&!scadrial(carried)||point<0||!HemalurgyService.enabled(charge.metal())||live.size()>=13||live.stream().anyMatch(i->i.point()==point||i.charge().id().equals(charge.id())))return false;var item=carried.copyWithCount(1);live.add(new Implant(point,u,v,item));write(p,live);menu.setCarried(ItemStack.EMPTY);if(!ImplantRules.compatible(charge.metal(),charge.power(),point))wound(p,point,0,false,true);apply(p);return true;}
    public static boolean remove(ServerPlayer p,int point){if(!p.isAlive()||p.isSpectator()||!screenAllowed(p)||!intact(p)||!p.containerMenu.getCarried().isEmpty())return false;var live=new ArrayList<>(implants(p));var implant=live.stream().filter(i->i.point()==point).findFirst().orElse(null);if(implant==null)return false;int before=live.size();double cost=HemalurgyConfig.SPIKE_COST.get()*(before>4&&!linchpin(p)?1+HemalurgyConfig.EXTRA_PENALTY.get():1);live.remove(implant);write(p,live);wound(p,point,cost,true,false);p.containerMenu.setCarried(implant.item().copy());apply(p);int cooldown=p.invulnerableTime;p.invulnerableTime=0;try{p.hurt(p.damageSources().magic(),(float)ImplantRules.removalDamage(point,before));}finally{p.invulnerableTime=Math.max(cooldown,p.invulnerableTime);}return true;}
    public static List<IdentityMath.Portion> powers(ServerPlayer p,String key){return powers(p,key,active(p));}
    private static List<IdentityMath.Portion> powers(ServerPlayer p,String key,List<Implant> active){var parts=new ArrayList<IdentityMath.Portion>();for(var i:active)if(i.charge().power().equals(key))for(var source:i.charge().sources())parts.add(new IdentityMath.Portion(source.identity(),source.strength()*accuracy(i)));double sum=parts.stream().mapToDouble(IdentityMath.Portion::strength).sum(),room=Math.max(0,1024-PowerAttributes.baseStrength(p,key)),scale=sum>room?room/sum:1;if(scale<=0)return List.of();return parts.stream().map(v->new IdentityMath.Portion(v.identity(),v.strength()*scale)).toList();}
    public static double resistance(ServerPlayer p){double zinc=0,copper=0;for(var i:active(p)){double r=i.charge().cognition().resistance()*accuracy(i);if(i.charge().metal().equals("zinc"))zinc+=r;else if(i.charge().metal().equals("copper"))copper+=r;}return 1-(1-Math.min(.4,zinc))*(1-Math.min(.25,copper));}
    public static double memoryBonus(ServerPlayer p){double sum=0;for(var i:active(p))sum+=i.charge().cognition().memoryCapacity()*accuracy(i);return Math.min(.75,sum);}
    private static ResourceLocation modifier(String name){return ResourceLocation.fromNamespaceAndPath("cosmerearcanists","implant_"+name.replace(':','_'));}
    private static void modifier(ServerPlayer p,net.minecraft.core.Holder<Attribute> key,String name,double amount,AttributeModifier.Operation operation){var a=p.getAttribute(key);if(a==null)return;var id=modifier(name);var old=a.getModifier(id);if(old!=null&&old.amount()==amount&&old.operation()==operation)return;if(old!=null)a.removeModifier(id);if(amount!=0)a.addTransientModifier(new AttributeModifier(id,amount,operation));}
    public static void apply(ServerPlayer p){var active=active(p);for(String key:PowerAttributes.keys()){double amount=powers(p,key,active).stream().mapToDouble(IdentityMath.Portion::strength).sum();var attr=PowerAttributes.instance(p,key);boolean had=attr!=null&&attr.getModifier(modifier(key))!=null;modifier(p,PowerAttributes.holder(key),key,amount,AttributeModifier.Operation.ADD_VALUE);if(had&&amount==0&&PowerAttributes.strength(p,key)<=0)PowerService.powerTransferred(p,key);}double strength=0,sight=0,hearing=0,touch=0;for(var i:active){double a=accuracy(i);var c=i.charge();if(c.power().equals(HemalurgicTraits.STRENGTH))strength+=c.strength()*a;sight+=c.senses().sight()*a;hearing+=c.senses().hearing()*a;touch+=c.senses().touch()*a;}modifier(p,Attributes.ATTACK_DAMAGE,"strength",strength,AttributeModifier.Operation.ADD_VALUE);modifier(p,PowerAttributes.SIGHT,"sight",sight,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);modifier(p,PowerAttributes.HEARING,"hearing",hearing,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);modifier(p,PowerAttributes.TOUCH,"touch",touch,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);boolean bad=misplaced(p);modifier(p,Attributes.MAX_HEALTH,"bad_health",bad?-.25:0,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);modifier(p,Attributes.ATTACK_DAMAGE,"bad_damage",bad?-.25:0,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);modifier(p,Attributes.MOVEMENT_SPEED,"bad_speed",bad?-.25:0,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);modifier(p,PowerAttributes.SIGHT,"bad_vision",bad?-.15:0,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);modifier(p,PowerAttributes.IMPLANT_VISION,"vision_limit",bad?-.15:0,AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);if(p.getHealth()>p.getMaxHealth())p.setHealth(p.getMaxHealth());}
    public static ItemStack display(Implant i){var item=i.item().copy();var root=item.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();var view=new CompoundTag();view.putInt("point",i.point());view.putDouble("u",i.u());view.putDouble("v",i.v());view.putDouble("accuracy",accuracy(i));root.put(DISPLAY,view);item.set(DataComponents.CUSTOM_DATA,CustomData.of(root));return item;}
    public static void registerProviders(){PowerSources.registerExternal(ImplantService::powers);IdentityAccess.registerImplanted(ImplantService::connections);}
    @SubscribeEvent public void tick(PlayerTickEvent.Post event){if(event.getEntity() instanceof ServerPlayer p){ScadrialVisits.observe(p);apply(p);}}
    @SubscribeEvent public void login(PlayerEvent.PlayerLoggedInEvent event){if(event.getEntity() instanceof ServerPlayer p){ScadrialVisits.observe(p);apply(p);}}
    @SubscribeEvent public void dimension(PlayerEvent.PlayerChangedDimensionEvent event){if(event.getEntity() instanceof ServerPlayer p)ScadrialVisits.observe(p);}
}
